import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';

export default function InfluencerProfile() {
    const navigate = useNavigate();
    const fileInputRef = useRef(null);
    const [profileData, setProfileData] = useState({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        platform: '',
        accountLink: '',
        bio: '',
        profileImage: null
    });
    const [loading, setLoading] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [previewImage, setPreviewImage] = useState(null);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Load actual user profile data from localStorage
        const loadUserProfile = () => {
            try {
                const storedUser = localStorage.getItem('studioUser');
                if (storedUser) {
                    const userData = JSON.parse(storedUser);
                    setProfileData({
                        firstName: userData.first_name || userData.firstName || '',
                        lastName: userData.last_name || userData.lastName || '',
                        email: userData.email || '',
                        phone: userData.phone || '',
                        platform: userData.platform || '',
                        accountLink: userData.account_link || userData.accountLink || '',
                        bio: userData.bio || '',
                        profileImage: userData.profile_image || userData.profileImage || null
                    });
                }
            } catch (error) {
                console.error('Error loading user profile:', error);
            }
        };

        loadUserProfile();
    }, []);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setProfileData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            // Validate file type
            const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif'];
            if (!validTypes.includes(file.type)) {
                toast.error('Please select a valid image file (JPEG, JPG, PNG, GIF)');
                return;
            }

            // Validate file size (5MB max)
            if (file.size > 5 * 1024 * 1024) {
                toast.error('File size should be less than 5MB');
                return;
            }

            const reader = new FileReader();
            reader.onload = (e) => {
                setPreviewImage(e.target.result);
                
                // Automatically enable edit mode when a new image is selected
                if (!isEditing) {
                    setIsEditing(true);
                }
            };
            reader.readAsDataURL(file);
        }
    };

    const triggerFileInput = () => {
        fileInputRef.current.click();
    };

    const handleSave = async () => {
        setLoading(true);
        try {
            // Update localStorage with new profile data
            const storedUser = localStorage.getItem('studioUser');
            if (storedUser) {
                const userData = JSON.parse(storedUser);
                
                // Update user data
                const updatedUser = {
                    ...userData,
                    first_name: profileData.firstName,
                    last_name: profileData.lastName,
                    email: profileData.email,
                    phone: profileData.phone,
                    platform: profileData.platform,
                    account_link: profileData.accountLink,
                    bio: profileData.bio,
                    profile_image: previewImage || profileData.profileImage
                };
                
                localStorage.setItem('studioUser', JSON.stringify(updatedUser));
                
                // Update profileData state with new image if applicable
                if (previewImage) {
                    setProfileData(prev => ({
                        ...prev,
                        profileImage: previewImage
                    }));
                }
                
                setIsEditing(false);
                setPreviewImage(null);
                toast.success('Profile updated successfully!');
            }
        } catch (error) {
            console.error('Error saving profile:', error);
            toast.error('Failed to save profile');
        } finally {
            setLoading(false);
        }
    };

    const handleCancel = () => {
        // Reset to original values
        const storedUser = localStorage.getItem('studioUser');
        if (storedUser) {
            const userData = JSON.parse(storedUser);
            setProfileData({
                firstName: userData.first_name || userData.firstName || '',
                lastName: userData.last_name || userData.lastName || '',
                email: userData.email || '',
                phone: userData.phone || '',
                platform: userData.platform || '',
                accountLink: userData.account_link || userData.accountLink || '',
                bio: userData.bio || '',
                profileImage: userData.profile_image || userData.profileImage || null
            });
        }
        setIsEditing(false);
        setPreviewImage(null);
    };

    const getImageSrc = () => {
        return previewImage || profileData.profileImage || '/assets/images/users/avatar-1.jpg';
    };

    return (
        <div className="container-fluid">
            {/* Header */}
            <div className="row">
                <div className="col-12">
                    <div className="page-title-box d-sm-flex align-items-center justify-content-between">
                        <h4 className="mb-sm-0">Profile</h4>
                    </div>
                </div>
            </div>

            <div className="row">
                {/* Profile Card */}
                <div className="col-lg-12">
                    <div className="card">
                        <div className="card-body">
                            {/* Profile Header with Ima ge and Info Side by Side */}
                            <div className="d-flex flex-wrap align-items-start gap-4 mb-4">
                                {/* Profile Image Section */}
                                <div className="position-relative">
                                    <div className="avatar-xl mx-auto">
                                        <img 
                                            src={getImageSrc()} 
                                            alt="Profile" 
                                            className="img-thumbnail rounded-circle"
                                            style={{ width: '120px', height: '120px', objectFit: 'cover' }}
                                        />
                                        <div 
                                            className="position-absolute bottom-0 end-0"
                                            style={{
                                                width: '40px',
                                                height: '40px',
                                                backgroundColor: '#007bff',
                                                borderRadius: '50%',
                                                display: 'flex',
                                                alignItems: 'center',
                                                justifyContent: 'center',
                                                cursor: 'pointer',
                                                border: '2px solid white'
                                            }}
                                            onClick={triggerFileInput}
                                        >
                                            <i className="ri-camera-fill text-white" style={{ fontSize: '20px' }}></i>
                                        </div>
                                    </div>
                                    <input 
                                        type="file" 
                                        ref={fileInputRef}
                                        onChange={handleFileChange}
                                        accept="image/*"
                                        className="d-none"
                                    />
                                </div>

                                {/* Profile Info Section */}
                                <div className="flex-grow-1 ms-3">
                                    <div className="row align-items-end">
                                        <div className="col-md-6">
                                            <div className="mb-3">
                                                <h5 className="mb-1">{profileData.firstName} {profileData.lastName}</h5>
                                                <p className="text-muted mb-0">{profileData.email}</p>
                                                <p className="text-muted mb-0">{profileData.phone}</p>
                                            </div>
                                        </div>
                                        <div className="col-md-6 text-md-end">
                                            <button 
                                                type="button" 
                                                className={`btn ${isEditing ? 'btn-success' : 'btn-primary'}`}
                                                onClick={isEditing ? handleSave : () => setIsEditing(true)}
                                                disabled={loading}
                                            >
                                                {isEditing ? (
                                                    loading ? 'Saving...' : 'Save Changes'
                                                ) : (
                                                    <>
                                                        <i className="ri-edit-line align-bottom me-1"></i>
                                                        Edit Profile
                                                    </>
                                                )}
                                            </button>
                                            {isEditing && (
                                                <button 
                                                    type="button" 
                                                    className="btn btn-soft-danger ms-2"
                                                    onClick={handleCancel}
                                                >
                                                    Cancel
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Divider */}
                            <div className="border-bottom border-bottom-dashed mt-4 mb-4"></div>

                            {/* Profile Details Form */}
                            <form>
                                <div className="row">
                                    <div className="col-lg-6">
                                        <div className="mb-3">
                                            <label htmlFor="firstName" className="form-label">First Name</label>
                                            <input 
                                                type="text" 
                                                className="form-control" 
                                                id="firstName"
                                                name="firstName"
                                                value={profileData.firstName}
                                                onChange={handleInputChange}
                                                disabled={!isEditing}
                                            />
                                        </div>
                                    </div>
                                    <div className="col-lg-6">
                                        <div className="mb-3">
                                            <label htmlFor="lastName" className="form-label">Last Name</label>
                                            <input 
                                                type="text" 
                                                className="form-control" 
                                                id="lastName"
                                                name="lastName"
                                                value={profileData.lastName}
                                                onChange={handleInputChange}
                                                disabled={!isEditing}
                                            />
                                        </div>
                                    </div>
                                    <div className="col-lg-6">
                                        <div className="mb-3">
                                            <label htmlFor="email" className="form-label">Email</label>
                                            <input 
                                                type="email" 
                                                className="form-control" 
                                                id="email"
                                                name="email"
                                                value={profileData.email}
                                                onChange={handleInputChange}
                                                disabled={!isEditing}
                                            />
                                        </div>
                                    </div>
                                    <div className="col-lg-6">
                                        <div className="mb-3">
                                            <label htmlFor="phone" className="form-label">Phone Number</label>
                                            <input 
                                                type="tel" 
                                                className="form-control" 
                                                id="phone"
                                                name="phone"
                                                value={profileData.phone}
                                                onChange={handleInputChange}
                                                disabled={!isEditing}
                                            />
                                        </div>
                                    </div>
                                    <div className="col-lg-6">
                                        <div className="mb-3">
                                            <label htmlFor="platform" className="form-label">Platform</label>
                                            <select 
                                                className="form-select" 
                                                id="platform"
                                                name="platform"
                                                value={profileData.platform}
                                                onChange={handleInputChange}
                                                disabled={!isEditing}
                                            >
                                                <option value="">Select Platform</option>
                                                <option value="Instagram">Instagram</option>
                                                <option value="YouTube">YouTube</option>
                                                <option value="TikTok">TikTok</option>
                                                <option value="Facebook">Facebook</option>
                                                <option value="Twitter">Twitter</option>
                                            </select>
                                        </div>
                                    </div>
                                    <div className="col-lg-6">
                                        <div className="mb-3">
                                            <label htmlFor="accountLink" className="form-label">Account Link</label>
                                            <input 
                                                type="url" 
                                                className="form-control" 
                                                id="accountLink"
                                                name="accountLink"
                                                value={profileData.accountLink}
                                                onChange={handleInputChange}
                                                disabled={!isEditing}
                                            />
                                        </div>
                                    </div>
                                    <div className="col-lg-12">
                                        <div className="mb-3">
                                            <label htmlFor="bio" className="form-label">Bio</label>
                                            <textarea 
                                                className="form-control" 
                                                id="bio"
                                                name="bio"
                                                rows="4"
                                                value={profileData.bio}
                                                onChange={handleInputChange}
                                                disabled={!isEditing}
                                            ></textarea>
                                        </div>
                                    </div>
                                </div>
                            </form>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
